import type { FC } from 'react';
import { motion, memo } from 'framer-motion';
import { Download, GraduationCap, Compass } from 'lucide-react';
import { Button } from '@/components/ui/button';
import portfolioData from '../data/portfolio.json';
import ContactSection from '../components/ContactSection';

const About: FC = () => {
  const { about } = portfolioData;

  // Memoized content section component
  const ContentSection = memo(() => (
    <section className="section-container py-12 md:py-20">
      <div className="grid md:grid-cols-2 gap-12 md:gap-16 items-start">
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
        >
          <div className="space-y-8">

            <div className="space-y-6">
              <h2 className="flex items-center gap-3 text-xl md:text-2xl font-display font-medium mb-6 border-b border-border pb-4">
                <GraduationCap className="text-accent" size={28} aria-hidden="true" />
                <span className="text-accent">Education</span>
              </h2>
              <div className="glass-panel p-6">
                <div className="space-y-2">
                  <h3 className="text-lg font-medium text-foreground">
                    {about.education}
                  </h3>
                  <p className="text-foreground/60 font-mono">
                    {about.alma_matter}
                  </p>
                </div>
              </div>
              <div className="flex justify-center">
                <motion.div
                  className="relative"
                  animate={{
                    y: [0, -10, 0],
                  }}
                  transition={{
                    duration: 4,
                    repeat: Infinity,
                    ease: "easeInOut"
                  }}
                >
                  {/* Elegant container with border */}
                  <div className="relative z-10">
                    <div className="relative">
                      
                      {/* Image container */}
                      <div className="relative rounded-[2.8rem] overflow-hidden p-6">
                        <img
                          src="/dev-illustration.webp"
                          alt="Developer illustration"
                          width={608}
                          height={411}
                          loading="lazy"
                          decoding="async"
                          className="w-full max-w-sm h-auto object-contain relative z-10 mx-auto"
                          style={{
                            filter: "drop-shadow(0 0 25px hsl(var(--accent-glow) / 0.4))"
                          }}
                        />
                      </div>
                    </div>
                  </div>
                </motion.div>
              </div>

              
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <h2 className="flex items-center gap-3 text-xl md:text-2xl font-display font-medium mb-6 border-b border-border pb-4">
            <Compass className="text-accent" size={28} aria-hidden="true" />
            <span className="text-accent">Beyond the Code</span>
          </h2>
          <p className="text-lg text-foreground/80 mb-8 leading-relaxed text-justify">When I'm not building data pipelines or fine-tuning cloud infrastructure, here's what keeps me inspired:</p>
          <ul className="space-y-4 text-foreground/80">
            {about.hobbies_and_interests.map((hobby, index) => (
              <li key={index} className="flex items-start gap-3">
                <span className="text-accent text-2xl" aria-hidden="true">•</span>
                <p className="text-lg text-justify">{hobby}</p>
              </li>
            ))}
          </ul>

        </motion.div>
      </div>
    </section>
  ));

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="min-h-screen pt-24"
    >
      {/* Hero section with floating profile image */}
      <section className="relative pb-12 md:pb-1 flex items-center overflow-hidden">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-primary/10 rounded-full blur-3xl"></div>
        </div>

        <div className="section-container relative z-20 max-w-6xl mx-auto">
          <div className="text-center mb-8 md:mb-12">
            <h1 className="text-2xl md:text-3xl font-display font-medium mb-6 text-accent">
              About Me
            </h1>
            <p className="text-muted-foreground max-w-2xl mx-auto text-xl font-light leading-relaxed">
              man behind the code
            </p>
          </div>

          <div className="grid md:grid-cols-2 gap-8 md:gap-12 items-center mt-8 md:mt-0">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.5 }}
              className="max-w-xl"
            >
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.5, delay: 0.2 }}
              >
                <div className="space-y-4">
                  <p className="text-lg md:text-xl text-foreground/80 leading-relaxed text-justify">
                    {about.summary}
                  </p>
                </div>

                <motion.div
                  className="flex flex-wrap justify-center md:justify-start gap-4 mb-8 mt-8"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.5, delay: 0.4 }}
                >
                  <Button size="lg" className="flex gap-2 items-center" asChild>
                    <a href={about.resume} target="_blank" rel="noopener noreferrer">
                      <Download size={18} />
                      Download Resume
                    </a>
                  </Button>
                </motion.div>
              </motion.div>
            </motion.div>

            <div className="flex justify-center items-center">
              <motion.div
                className="w-[300px] h-[300px]"
                animate={{ y: [0, -10, 0] }}
                transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
              >
                <img
                  src="/unnamed.webp"
                  alt="Shravan"
                  width={600}
                  height={800}
                  fetchPriority="high"
                  decoding="async"
                  className="w-full h-full object-cover rounded-2xl border border-border shadow-glow"
                />
              </motion.div>
            </div>
          </div>
        </div>
      </section>

      <ContentSection />

      <div className="bg-background">
        <ContactSection />
      </div>
    </motion.div>
  );
};

export default About;
