import type { FC } from 'react';
import { Mail, Github, Linkedin, Twitter, Instagram } from 'lucide-react';
import { motion } from 'framer-motion';
import portfolioData from '../data/portfolio.json';

interface ContactMethod {
  name: string;
  icon: JSX.Element;
  href: string;
  color: string;
}

const ContactSection: FC = () => {
  const { social } = portfolioData;
  
  const contactMethods: ContactMethod[] = [
    {
      name: 'Email',
      icon: <Mail size={28} />,
      href: `mailto:${social.email}`,
      color: 'from-red-500 to-pink-500',
    },
    {
      name: 'LinkedIn',
      icon: <Linkedin size={28} />,
      href: social.linkedin,
      color: 'from-blue-500 to-blue-600',
    },
    {
      name: 'GitHub',
      icon: <Github size={28} />,
      href: social.github,
      color: 'from-gray-600 to-gray-800',
    },
    {
      name: 'Twitter',
      icon: <Twitter size={28} />,
      href: social.twitter,
      color: 'from-sky-400 to-blue-500',
    },
    {
      name: 'Instagram',
      icon: <Instagram size={28} />,
      href: social.instagram,
      color: 'from-purple-500 via-pink-500 to-orange-400',
    },
  ];

  return (
    <section className="section-container" id="contact">
      <div className="text-center mb-12">
        <h2 className="text-xl md:text-2xl font-display font-medium mb-4 text-accent">Get In Touch</h2>
        <p className="text-muted-foreground max-w-2xl mx-auto">
          Interested in working together? Feel free to reach out through any of these channels.
        </p>
      </div>
      
      <div className="flex justify-center items-center gap-4 sm:gap-8 md:gap-12 max-w-4xl mx-auto">
        {contactMethods.map((method, index) => (
          <motion.a
            key={method.name}
            href={method.href}
            target="_blank"
            rel="noopener noreferrer"
            aria-label={method.name}
            className="group relative rounded-full"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.95 }}
          >
            {/* Background glow effect */}
            <div className={`absolute inset-0 bg-gradient-to-br ${method.color} rounded-full blur-lg opacity-0 group-hover:opacity-40 group-focus-visible:opacity-40 transition-opacity duration-300`}></div>

            {/* Icon with gradient background */}
            <div className={`relative z-10 text-white bg-gradient-to-br ${method.color} p-3 sm:p-4 rounded-full group-hover:shadow-glow transition-all duration-300`}>
              {method.icon}
            </div>

            {/* Tooltip - visible on hover and keyboard focus */}
            <div className="absolute -bottom-12 left-1/2 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 group-focus-visible:opacity-100 transition-opacity duration-300 pointer-events-none">
              <div className="bg-background/90 backdrop-blur-sm border border-border rounded-lg px-3 py-2 text-sm font-medium text-foreground whitespace-nowrap">
                {method.name}
              </div>
              <div className="absolute top-0 left-1/2 transform -translate-x-1/2 -translate-y-1 w-2 h-2 bg-background/90 border-l border-t border-border rotate-45"></div>
            </div>
          </motion.a>
        ))}
      </div>
      
      <div className="mt-16 text-center text-muted-foreground">
        <p>© {new Date().getFullYear()} {portfolioData.name}. All rights reserved.</p>
      </div>
    </section>
  );
};

export default ContactSection;
